// Independent Lagrange polynomial and passive Rodrigues algebra on the
// shared frame-definition table. No GMAT conversion/interpolator is called.
static std::array<double,6> inIcrf(const std::vector<std::array<double,4>> &table,double epoch,const std::array<double,6> &state,QJsonObject *record=nullptr){
 int lo=0,hi=static_cast<int>(table.size())-1,mid=-1;while(lo<hi-1){mid=(lo+hi)/2;if(epoch>table[mid][0])lo=mid;else hi=mid;}require(mid>=0&&epoch>=table.front()[0]&&epoch<=table.back()[0],"SPK frame table epoch outside shared definition");int first=std::max(0,mid-4),last=std::min(static_cast<int>(table.size())-1,first+9);first=std::max(0,last-9);require(last-first==9,"SPK frame stencil incomplete");std::array<double,3> rv{};QJsonArray samples;
 for(int i=first;i<=last;++i){double weight=1;for(int j=first;j<=last;++j)if(i!=j)weight*=(epoch-table[j][0])/(table[i][0]-table[j][0]);for(int j=0;j<3;++j)rv[j]+=weight*table[i][j+1];samples.append(QJsonArray{table[i][0],table[i][1],table[i][2],table[i][3]});}
 const double angle=std::sqrt(rv[0]*rv[0]+rv[1]*rv[1]+rv[2]*rv[2]);require(angle>0&&std::isfinite(angle),"SPK frame rotation vector invalid");std::array<double,3>a{rv[0]/angle,rv[1]/angle,rv[2]/angle};std::array<double,6> result{};for(int offset:{0,3}){const double x=state[offset],y=state[offset+1],z=state[offset+2],dot=a[0]*x+a[1]*y+a[2]*z;const std::array<double,3>cross{a[1]*z-a[2]*y,a[2]*x-a[0]*z,a[0]*y-a[1]*x};for(int j=0;j<3;++j)result[offset+j]=std::cos(angle)*state[offset+j]-std::sin(angle)*cross[j]+(1-std::cos(angle))*dot*a[j];}
 if(record)*record=QJsonObject{{"a1_epoch",epoch},{"first_index",first},{"samples",samples},{"rotation_vector",QJsonArray{rv[0],rv[1],rv[2]}}};return result;
}
